(() => {
  const stockDataEl = document.getElementById('stock-data');
  const historyDataEl = document.getElementById('history-data');

  const embeddedStockData = stockDataEl ? JSON.parse(stockDataEl.textContent) : null;
  const embeddedHistoryData = historyDataEl ? JSON.parse(historyDataEl.textContent) : null;

  const tooltip = d3.select('#tooltip');

  const formatCap = (value) => {
    if (value == null || Number.isNaN(value)) return 'N/A';
    const out = d3.format('.3s')(value);
    return out.replace('G', 'B');
  };

  const parseCap = (value) => {
    if (value == null || value === '') return null;
    const num = Number(value);
    return Number.isNaN(num) ? null : num;
  };

  const parseRow = (row) => ({
    ticker: row.ticker,
    sector: row.sector || 'Unknown',
    fullName: row['full name'] || row.fullName || row.name || 'Unknown',
    marketCap: parseCap(row.marketCap),
    country: row.country || null,
    website: row.website || null
  });

  const loadStockData = () => {
    if (embeddedStockData) return Promise.resolve(embeddedStockData);
    return d3.csv('data/stock-descriptions.csv', parseRow);
  };

  const getHistorySeries = (ticker) => {
    if (embeddedHistoryData && embeddedHistoryData[ticker]) {
      return Promise.resolve(embeddedHistoryData[ticker]);
    }
    return d3.csv(`data/indiv-stock/${ticker}.csv`, (row) => ({
      date: row.Date,
      close: Number(row.Close)
    }));
  };

  const init = (data) => {
    data.forEach((d) => {
      d.isEtf = d.sector === 'ETF' || d.marketCap == null;
    });

    const sectors = Array.from(new Set(data.map((d) => d.sector))).sort();

    const chartEl = document.getElementById('bubble-chart');
    const width = 820;
    const height = 540;

    const svg = d3.select(chartEl)
      .append('svg')
      .attr('viewBox', `0 0 ${width} ${height}`)
      .attr('preserveAspectRatio', 'xMidYMid meet');

    const g = svg.append('g');

    const color = d3.scaleOrdinal()
      .domain(sectors)
      .range(d3.schemeTableau10);

    const caps = data.filter((d) => d.marketCap != null).map((d) => d.marketCap);
    const minCap = d3.min(caps);
    const maxCap = d3.max(caps);
    const radiusScale = d3.scaleSqrt()
      .domain([minCap, maxCap])
      .range([14, 60]);

    const nodes = data.map((d) => ({
      ...d,
      radius: d.marketCap ? radiusScale(d.marketCap) : 18
    }));

    const columns = Math.ceil(Math.sqrt(sectors.length));
    const rows = Math.ceil(sectors.length / columns);
    const gridWidth = width * 0.7;
    const gridHeight = height * 0.6;
    const startX = (width - gridWidth) / 2;
    const startY = (height - gridHeight) / 2;
    const xSpacing = gridWidth / Math.max(columns - 1, 1);
    const ySpacing = gridHeight / Math.max(rows - 1, 1);

    const centers = new Map();
    sectors.forEach((sector, index) => {
      const col = index % columns;
      const row = Math.floor(index / columns);
      centers.set(sector, {
        x: startX + col * xSpacing,
        y: startY + row * ySpacing
      });
    });

    const simulation = d3.forceSimulation(nodes)
      .force('x', d3.forceX((d) => centers.get(d.sector).x).strength(0.25))
      .force('y', d3.forceY((d) => centers.get(d.sector).y).strength(0.25))
      .force('collide', d3.forceCollide((d) => d.radius + 1.5).iterations(2))
      .force('charge', d3.forceManyBody().strength(-6))
      .alpha(1)
      .alphaDecay(0.03);

    const node = g.selectAll('g.node')
      .data(nodes, (d) => d.ticker)
      .enter()
      .append('g')
      .attr('class', 'node');

    node.append('circle')
      .attr('r', (d) => d.radius)
      .attr('fill', (d) => color(d.sector));

    node.append('text')
      .attr('class', 'label')
      .attr('text-anchor', 'middle')
      .attr('dy', '0.35em')
      .style('font-size', (d) => `${Math.max(9, Math.min(15, d.radius / 2.2))}px`)
      .text((d) => d.ticker);

    simulation.on('tick', () => {
      node.attr('transform', (d) => `translate(${d.x},${d.y})`);
    });

    const legend = d3.select('#legend');
    const legendItems = legend.selectAll('.legend-item')
      .data(sectors)
      .enter()
      .append('div')
      .attr('class', 'legend-item');

    legendItems.append('span')
      .attr('class', 'legend-swatch')
      .style('background', (d) => color(d));

    legendItems.append('span')
      .text((d) => d);

    node
      .on('mouseenter', (event, d) => {
        if (d.isEtf) return;
        tooltip
          .style('opacity', 1)
          .html(`<strong>${d.ticker}</strong><br>${d.fullName}<br>${d.sector}`);
      })
      .on('mousemove', (event, d) => {
        if (d.isEtf) return;
        tooltip
          .style('left', `${event.pageX + 14}px`)
          .style('top', `${event.pageY + 14}px`);
      })
      .on('mouseleave', () => {
        tooltip.style('opacity', 0);
      });

    const table = d3.select('#table-container')
      .append('table')
      .attr('class', 'stock-table');

    table.append('thead')
      .append('tr')
      .selectAll('th')
      .data(['Ticker symbol', 'Full company name', 'Sector', 'Market cap'])
      .enter()
      .append('th')
      .text((d) => d);

    const tbody = table.append('tbody');

    const rowsSel = tbody.selectAll('tr')
      .data(data, (d) => d.ticker)
      .enter()
      .append('tr')
      .attr('data-ticker', (d) => d.ticker);

    rowsSel.append('td').text((d) => d.ticker);
    rowsSel.append('td').text((d) => d.fullName);
    rowsSel.append('td').text((d) => d.sector);
    rowsSel.append('td').attr('class', 'cap').text((d) => formatCap(d.marketCap));

    let selectedId = null;

    const historyTitle = d3.select('#history-title');
    const historyEmpty = d3.select('#history-empty');
    const historyChart = d3.select('#history-chart');

    const clearHistory = (message) => {
      historyChart.selectAll('*').remove();
      historyEmpty.text(message).style('display', 'block');
      historyTitle.text('Selected stock price history');
    };

    const renderHistory = (ticker, series) => {
      historyChart.selectAll('*').remove();
      if (!series || !series.length) {
        clearHistory('No price history available for this ticker.');
        return;
      }
      const parseDate = d3.timeParse('%Y-%m-%d');
      const values = series
        .map((d) => ({
          date: parseDate(d.date),
          close: Number(d.close)
        }))
        .filter((d) => d.date && !Number.isNaN(d.close));

      values.sort((a, b) => a.date - b.date);
      const sliced = values.slice(-180);

      historyEmpty.style('display', 'none');

      const width = 520;
      const height = 180;
      const margin = { top: 16, right: 18, bottom: 24, left: 44 };

      const svgHistory = historyChart
        .append('svg')
        .attr('viewBox', `0 0 ${width} ${height}`)
        .attr('preserveAspectRatio', 'xMidYMid meet');

      const x = d3.scaleTime()
        .domain(d3.extent(sliced, (d) => d.date))
        .range([margin.left, width - margin.right]);

      const y = d3.scaleLinear()
        .domain(d3.extent(sliced, (d) => d.close))
        .nice()
        .range([height - margin.bottom, margin.top]);

      const line = d3.line()
        .x((d) => x(d.date))
        .y((d) => y(d.close));

      svgHistory.append('path')
        .datum(sliced)
        .attr('class', 'history-line')
        .attr('d', line);

      svgHistory.append('g')
        .attr('transform', `translate(0,${height - margin.bottom})`)
        .call(d3.axisBottom(x).ticks(4).tickSizeOuter(0))
        .call((gAxis) => gAxis.selectAll('text').attr('dy', '1.4em'));

      svgHistory.append('g')
        .attr('transform', `translate(${margin.left},0)`)
        .call(d3.axisLeft(y).ticks(4).tickSizeOuter(0));

      const first = sliced[0].close;
      const last = sliced[sliced.length - 1].close;
      const change = ((last - first) / first) * 100;
      const changeText = `${change >= 0 ? '+' : ''}${change.toFixed(1)}%`;
      historyTitle.text(`${ticker} · last close $${last.toFixed(2)} (${changeText})`);
    };

    const showHistory = (ticker) => {
      if (!ticker) {
        clearHistory('Select a stock to see its price history.');
        return;
      }
      historyEmpty.text('Loading price history...').style('display', 'block');
      getHistorySeries(ticker)
        .then((series) => {
          renderHistory(ticker, series);
        })
        .catch(() => {
          clearHistory('Unable to load price history for this ticker.');
        });
    };

    const selectById = (id) => {
      if (selectedId === id) {
        selectedId = null;
        node.classed('selected', false);
        rowsSel.classed('selected', false);
        clearHistory('Select a stock to see its price history.');
        return;
      }
      selectedId = id;
      node.classed('selected', (d) => d.ticker === id);
      rowsSel.classed('selected', (d) => d.ticker === id);
      showHistory(id);
    };

    node.on('click', (event, d) => {
      selectById(d.ticker);
    });

    rowsSel.on('click', (event, d) => {
      selectById(d.ticker);
    });

    clearHistory('Select a stock to see its price history.');
  };

  loadStockData()
    .then((data) => init(data))
    .catch((error) => {
      console.error('Failed to load data', error);
      d3.select('#bubble-chart').append('div').attr('class', 'error')
        .text('Unable to load stock data.');
    });
})();
EOF"}

